            padding: 0 1.25rem;
        }
        section {
            padding: 3rem 0;
            border-bottom: 1px solid var(--border);
        }
        section:last-child {
            border-bottom: none;
        }
        .progress-bar-wrap {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: rgba(31, 64, 96, .3);
            z-index: 2000;
        }
        .progress-bar {
            height: 100%;
            background: linear-gradient(90deg, var(--blue), var(--blue-lt));
            width: 0%;
            transition: width .2s;
        }
        .nav-bar {
            position: fixed;
            top: 3px;
            left: 0;
            right: 0;
            background: rgba(11, 18, 28, .97);
            backdrop-filter: blur(16px);
            border-bottom: 1px solid var(--border);
            z-index: 1000;
        }
        .nav-inner {
            max-width: 860px;
            margin: 0 auto;
            padding: .6rem 1.25rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 1rem;
        }
        .brand {
            display: flex;
            align-items: center;
            gap: .5rem;
            text-decoration: none;
            color: #fff;
            font-weight: 800;
            font-size: .85rem;
            letter-spacing: .08em;
        }
        .brand-icon {
            width: 2rem;
            height: 2rem;
            border-radius: 6px;
            background: linear-gradient(145deg, var(--blue), var(--blue-deep));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.1rem;
        }
        .nav-links {
            display: flex;
            gap: 1.2rem;
            list-style: none;
        }
        .nav-links a {
            color: var(--muted);
            text-decoration: none;
            font-size: .72rem;
            font-weight: 600;
            transition: color .2s;
            letter-spacing: .04em;
        }
        .nav-links a:hover {
            color: var(--gold);
        }
        @media(max-width:680px) {
            .nav-links {
                display: none;
            }
        }
        .menu-toggle {
            display: none;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            background: rgba(75, 139, 190, .1);
            border: 1px solid var(--border);
            border-radius: 6px;
            width: 40px;
            height: 40px;
            cursor: pointer;
            gap: 4px;
        }
        .menu-toggle span {
            width: 18px;
            height: 2px;
            background: #fff;
            border-radius: 2px;
            transition: .25s;
        }
        .menu-toggle.active span:nth-child(1) {
            transform: rotate(45deg) translate(5px, 5px);
        }
        .menu-toggle.active span:nth-child(2) {
            opacity: 0;
        }
        .menu-toggle.active span:nth-child(3) {
            transform: rotate(-45deg) translate(5px, -5px);
        }
        @media(max-width:680px) {
            .menu-toggle {
                display: flex;
            }
        }
        .drawer-overlay {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, .8);
            z-index: 1050;
            opacity: 0;
            visibility: hidden;
            transition: .2s;
            backdrop-filter: blur(4px);
        }
        .drawer-overlay.active {
            opacity: 1;
            visibility: visible;
        }
        .mobile-drawer {
            position: fixed;
            top: 0;
            right: -300px;
            width: 280px;
            height: 100vh;
            background: var(--panel);
            border-left: 1px solid var(--border);
            z-index: 1100;
            display: flex;
            flex-direction: column;
            transition: right .3s;
            box-shadow: -5px 0 30px rgba(0, 0, 0, .5);
        }
        .mobile-drawer.active {
            right: 0;
        }
        .drawer-hd {
            padding: .8rem;
            border-bottom: 1px solid var(--border);
            display: flex;
            justify-content: flex-end;
        }
        .drawer-close {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            border: 1px solid var(--border);
            background: transparent;
            color: var(--muted);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .drawer-body {
            flex: 1;
            overflow-y: auto;
            padding: .8rem;
        }
        .drawer-body li {
            list-style: none;
            margin-bottom: .5rem;
        }
        .drawer-body a,
        .drawer-body button {
            display: flex;
            align-items: center;
            gap: .6rem;
            width: 100%;
            padding: .7rem .9rem;
            background: rgba(75, 139, 190, .12);
            border: 1px solid var(--border);
            border-radius: 8px;
            color: var(--text);
            font-size: .78rem;
            font-weight: 600;
            cursor: pointer;
            text-decoration: none;
            transition: background .2s;
        }
        .drawer-body a:active,
        .drawer-body button:active {
            background: rgba(75, 139, 190, .3);
        }
        .drawer-body i {
            color: var(--gold);
            width: 1.2rem;
        }
        h1,
        h2,
        h3,
        h4,
        h5 {
            font-family: ''Syne'', sans-serif;
            line-height: 1.25;
            font-weight: 700;
        }
        h1 {
            font-size: 1.6rem;
        }
        h2 {
            font-size: 1.25rem;
            margin-bottom: .5rem;
        }
        h3 {
            font-size: .95rem;
        }
        h4 {
            font-size: .85rem;
        }
        p {
            font-size: .82rem;
            color: var(--muted);
            line-height: 1.7;
        }
        code {
            font-family: ''JetBrains Mono'', monospace;
            font-size: .75rem;
            color: #a5d6ff;
        }
        .section-label {
            font-size: .65rem;
            font-weight: 800;
            letter-spacing: .12em;
            text-transform: uppercase;
            color: var(--muted);
            display: flex;
            align-items: center;
            gap: .6rem;
            margin-bottom: 1.2rem;
        }
        .section-label::before,
        .section-label::after {
            content: '''';
            flex: 1;
            height: 1px;
            background: var(--border);
        }
        .section-intro {
            max-width: 640px;
            margin: 0 auto .5rem;
            text-align: center;
        }
        .section-intro h2 {
            color: var(--text);
        }
        .section-intro p {
            font-size: .8rem;
        }
        .btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: .5rem;
            height: var(--btn-h);
            padding: 0 1.4rem;
            border-radius: var(--btn-r);
            font-family: ''Syne'', sans-serif;
            font-weight: 700;
            font-size: .78rem;
            cursor: pointer;
            transition: all .2s;
            border: none;
            text-decoration: none;
            white-space: nowrap;
        }
        .btn-primary {
            background: linear-gradient(135deg, var(--blue), var(--blue-deep));
            color: #fff;
            box-shadow: 0 4px 14px rgba(75, 139, 190, .35);
        }
        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 20px rgba(75, 139, 190, .45);
        }
        .btn-primary:active {
            transform: scale(.97);
        }
        .btn-outline {
            background: transparent;
            border: 1px solid var(--border);
            color: var(--text);
        }
        .btn-outline:hover {
            border-color: var(--blue);
            background: rgba(75, 139, 190, .08);
        }
        @media(max-width:480px) {
            .btn {
                width: 100%;
            }
        }
        .hero {
            padding: 5rem 0 3rem;
            background: radial-gradient(ellipse 80% 60% at 50% -10%, rgba(75, 139, 190, .18) 0%, transparent 70%);
        }
        .hero-tag {
            display: inline-flex;
            align-items: center;
            gap: .5rem;
            border: 1px solid var(--border);
            border-radius: 40px;
            padding: .3rem .9rem;
            font-size: .68rem;
            font-weight: 600;
            letter-spacing: .04em;
            margin-bottom: 1.2rem;
            background: var(--card);
        }
        .live-dot {
            width: 7px;
            height: 7px;
            background: var(--blue-lt);
            border-radius: 50%;
            animation: pulse 2s infinite;
        }
        @keyframes pulse {
            0%,
            100% {
                opacity: 1;
                transform: scale(1);
            }
            50% {
                opacity: .5;
                transform: scale(.8);
            }
        }
        .hero h1 {
            font-size: clamp(1.6rem, 4vw, 2.4rem);
            color: var(--gold);
            margin-bottom: .8rem;
        }
        .hero p.lead {
            font-size: .88rem;
            color: var(--muted);
            max-width: 560px;
            margin-bottom: 1.6rem;
            line-height: 1.75;
        }
        .hero-btns {
            display: flex;
            flex-direction: column;
            gap: .6rem;
            margin-bottom: 2rem;
        }
        .metrics-row {
            display: flex;
            flex-direction: column;
            gap: var(--gap);
            margin-bottom: 2rem;
        }
        .metric-tile {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1.1rem;
            text-align: center;
        }
        .metric-tile .num {
            font-size: 1.4rem;
            font-weight: 800;
            color: var(--gold);
            line-height: 1.1;
        }
        .metric-tile .lbl {
            font-size: .68rem;
            color: var(--muted);
            margin-top: .2rem;
        }
        .metric-tile .stars i {
            color: #ffb83b;
            font-size: .65rem;
        }
        .code-preview {
            background: var(--code-bg);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            overflow: hidden;
            margin-top: 1.5rem;
        }
        .code-chrome {
            background: #0a1a24;
            padding: .6rem .9rem;
            display: flex;
            align-items: center;
            gap: .6rem;
            border-bottom: 1px solid var(--border);
        }
        .dots {
            display: flex;
            gap: .35rem;
        }
        .dots span {
            width: 10px;
            height: 10px;
            border-radius: 50%;
        }
        .dot-r {
            background: #ff5f56;
        }
        .dot-y {
            background: #ffbd2e;
        }
        .dot-g {
            background: #27c93f;
        }
        .win-title {
            font-size: .68rem;
            color: var(--muted);
            font-family: ''JetBrains Mono'', monospace;
            margin-left: .4rem;
        }
        .code-body {
            padding: 1rem;
            overflow-x: auto;
            font-family: ''JetBrains Mono'', monospace;
            font-size: .76rem;
            line-height: 1.7;
        }
        .code-body pre {
            margin: 0;
            white-space: pre-wrap;
            word-break: break-word;
        }
        .terminal {
            background: #0a1a24;
            border-top: 1px solid var(--border);
            padding: .7rem 1rem;
            font-family: ''JetBrains Mono'', monospace;
            font-size: .76rem;
            color: #4ade80;
        }
        .card-grid {
            display: flex;
            flex-direction: column;
            gap: var(--gap);
        }
        .card {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1.25rem;
            display: flex;
            flex-direction: column;
            gap: .55rem;
            transition: border-color .2s, transform .2s, box-shadow .2s;
            text-decoration: none;
            color: inherit;
            cursor: pointer;
            min-height: 140px;
        }
        .card:hover {
            border-color: var(--blue);
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(75, 139, 190, .16);
        }
        .card:active {
            transform: scale(.98);
        }
        .card-icon {
            font-size: 1.5rem;
            line-height: 1;
        }
        .card h3,
        .card h4 {
            font-size: .82rem;
            color: var(--text);
        }
        .card p {
            font-size: .74rem;
            margin: 0;
        }
        .card-arrow {
            margin-top: auto;
            font-size: .65rem;
            color: var(--blue);
            opacity: 0;
            transition: opacity .2s, transform .2s;
        }
        .card:hover .card-arrow {
            opacity: 1;
            transform: translateX(3px);
        }
        .card-meta {
            display: flex;
            align-items: center;
            gap: .5rem;
            flex-wrap: wrap;
            margin-top: .2rem;
        }
        .lesson-count {
            font-size: .6rem;
            color: var(--teal);
            background: rgba(45, 212, 191, .1);
            border: 1px solid rgba(45, 212, 191, .2);
            border-radius: 20px;
            padding: .1rem .45rem;
        }
        .new-badge {
            font-size: .58rem;
            background: rgba(251, 146, 60, .15);
            color: var(--orange);
            border: 1px solid rgba(251, 146, 60, .25);
            border-radius: 20px;
            padding: .1rem .45rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: .05em;
        }
        .badge {
            display: inline-block;
            padding: .12rem .55rem;
            border-radius: 20px;
            font-size: .6rem;
            font-weight: 700;
        }
        .badge-beg {
            background: rgba(16, 185, 129, .15);
            color: #10b981;
        }
        .badge-int {
            background: rgba(245, 158, 11, .15);
            color: #f59e0b;
        }
        .badge-adv {
            background: rgba(139, 92, 246, .15);
            color: #a78bfa;
        }
        .badge-exp {
            background: rgba(239, 68, 68, .15);
            color: #f87171;
        }
        .badge-oop {
            background: rgba(75, 139, 190, .15);
            color: var(--blue-lt);
        }
        .badge-new {
            background: rgba(251, 146, 60, .15);
            color: var(--orange);
        }
        .tags {
            display: flex;
            flex-wrap: wrap;
            gap: .3rem;
            margin-top: .3rem;
        }
        .tag {
            font-size: .6rem;
            background: rgba(75, 139, 190, .1);
            border: 1px solid rgba(75, 139, 190, .2);
            border-radius: 20px;
            padding: .1rem .45rem;
            color: var(--blue-lt);
        }
        .card.oop-enc {
            border-color: #2a6496;
        }
        .card.oop-enc:hover {
            border-color: var(--blue);
        }
        .card.oop-inh {
            border-color: #1a6b3a;
        }
        .card.oop-inh:hover {
            border-color: #22c55e;
        }
        .card.oop-abs {
            border-color: #6b5700;
        }
        .card.oop-abs:hover {
            border-color: var(--gold);
        }
        .card.oop-pol {
            border-color: #6b3096;
        }
        .card.oop-pol:hover {
            border-color: #a855f7;
        }
        .stats-2 {
            display: flex;
            flex-direction: column;
            gap: var(--gap);
        }
        .stat-card {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1.1rem;
            text-align: center;
            min-height: 80px;
            display: flex;
            flex-direction: column;
            justify-content: center;
        }
        .stat-card .big {
            font-size: 1.5rem;
            font-weight: 800;
            color: var(--gold);
        }
        .stat-card .sm {
            font-size: .7rem;
            color: var(--muted);
            margin-top: .2rem;
        }
        .checklist {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: .4rem;
        }
        .checklist li {
            display: flex;
            gap: .55rem;
            align-items: flex-start;
            font-size: .78rem;
            color: var(--muted);
            padding: .5rem;
            border-bottom: 1px dashed var(--border);
        }
        .checklist li:last-child {
            border-bottom: none;
        }
        .checklist li span.check {
            color: var(--blue);
            flex-shrink: 0;
            margin-top: .1rem;
        }
        .roadmap {
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }
        .roadmap-step {
            display: flex;
            flex-direction: column;
            gap: .6rem;
        }
        .step-num {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            flex-shrink: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 800;
            font-size: .78rem;
        }
        .step-body {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1rem;
            flex: 1;
        }
        .step-title {
            font-size: .82rem;
            font-weight: 700;
            color: var(--gold);
            margin-bottom: .3rem;
        }
        .table-wrap {
            overflow-x: auto;
            margin-top: 1rem;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            font-size: .76rem;
            min-width: 480px;
        }
        thead tr {
            background: var(--card);
            border-bottom: 2px solid var(--blue);
        }
        th {
            padding: .75rem .8rem;
            text-align: left;
        }
        th:first-child {
            color: var(--gold);
        }
        th:nth-child(2) {
            color: var(--blue);
        }
        td {
            padding: .65rem .8rem;
            border-bottom: 1px solid var(--border);
            color: var(--muted);
        }
        td:nth-child(2) {
            color: var(--green);
            font-weight: 600;
        }
        tbody tr:nth-child(even) {
            background: rgba(75, 139, 190, .03);
        }
        .faq-list {
            display: flex;
            flex-direction: column;
            gap: .6rem;
        }
        .faq-item {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            overflow: hidden;
        }
        .faq-q {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 1rem 1.1rem;
            cursor: pointer;
            gap: .8rem;
            min-height: var(--btn-h);
        }
        .faq-q h3 {
            font-size: .8rem;
            font-weight: 600;
            color: var(--text);
            flex: 1;
        }
        .faq-toggle {
            font-size: .9rem;
            color: var(--blue);
            width: 20px;
            text-align: center;
            flex-shrink: 0;
        }
        .faq-a {
            max-height: 0;
            overflow: hidden;
            transition: max-height .28s ease, padding .28s;
        }
        .faq-a.open {
            max-height: 300px;
            padding: 0 1.1rem 1rem;
        }
        .faq-a p {
            font-size: .78rem;
        }
        .instructor-wrap {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 1.5rem;
        }
        .avatar {
            width: 120px;
            height: 120px;
            border-radius: 50%;
            border: 2px solid var(--border);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 3rem;
            flex-shrink: 0;
        }
        .creds {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: .4rem;
        }
        .creds li {
            display: flex;
            align-items: center;
            gap: .6rem;
            font-size: .76rem;
            color: var(--muted);
            padding: .45rem 0;
            border-bottom: 1px dashed var(--border);
        }
        .creds li i {
            color: var(--gold);
            width: 1rem;
        }
        .social-row {
            display: flex;
            flex-direction: row;
            gap: .5rem;
            margin-top: .8rem;
            flex-wrap: wrap;
        }
        .social-btn {
            width: 44px;
            height: 44px;
            border-radius: 50%;
            background: var(--card);
            border: 1px solid var(--border);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--muted);
            text-decoration: none;
            font-size: .85rem;
            transition: .2s;
        }
        .social-btn:hover {
            border-color: var(--blue);
            color: var(--blue-lt);
        }
        blockquote {
            font-family: ''Crimson Pro'', serif;
            font-style: italic;
            font-size: .9rem;
            color: var(--text);
            line-height: 1.6;
            margin-bottom: .6rem;
        }
        .testi-meta {
            display: flex;
            align-items: center;
            gap: .6rem;
        }
        .testi-ava {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: var(--panel);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: .9rem;
        }
        .testi-name {
            font-size: .75rem;
            font-weight: 700;
            color: var(--text);
        }
        .testi-role {
            font-size: .68rem;
            color: var(--muted);
        }
        .achiev {
            display: inline-block;
            margin-top: .6rem;
            padding: .18rem .65rem;
            border-radius: 20px;
            font-size: .62rem;
            background: rgba(75, 139, 190, .12);
            border: 1px solid rgba(75, 139, 190, .25);
            color: var(--blue-lt);
        }
        .cat-label {
            display: flex;
            align-items: center;
            gap: .5rem;
            font-size: .68rem;
            font-weight: 700;
            color: var(--gold);
            letter-spacing: .06em;
            text-transform: uppercase;
            margin: 1.8rem 0 .8rem;
        }
        .oop-block {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1.3rem;
            margin-bottom: 1.2rem;
        }
        .oop-block h3 {
            font-size: .88rem;
            color: var(--gold);
            margin-bottom: .6rem;
            display: flex;
            align-items: center;
            gap: .4rem;
        }
        .oop-block p {
            font-size: .78rem;
            margin-bottom: .8rem;
        }
        .code-snippet {
            background: var(--code-bg);
            border-radius: 6px;
            border-left: 3px solid var(--blue);
            padding: .9rem 1rem;
            overflow-x: auto;
            margin-bottom: .7rem;
            position: relative;
        }
        .code-snippet pre {
            font-family: ''JetBrains Mono'', monospace;
            font-size: .73rem;
            line-height: 1.65;
