    <style>
        :root {
            --bg: #0B121C;
            --panel: #0F1C2F;
            --card: #111e30;
            --border: #1F4060;
            --blue: #4B8BBE;
            --blue-deep: #306998;
            --blue-lt: #78B9E6;
            --gold: #FFD966;
            --text: #E2E8F0;
            --muted: #8BA3BF;
            --code-bg: #0A1A24;
            --green: #10B981;
            --amber: #F59E0B;
            --red: #EF4444;
