        .page-col {
            width: 100%;
            max-width: 860px;
            margin: 0 auto;
            padding: 0 1.25rem;
        }
        section {
            padding: 2.5rem 0;
            border-bottom: 1px solid var(--border);
        }
        section:last-child {
            border-bottom: none;
        }
        .progress-bar-wrap {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: rgba(31, 64, 96, .3);
