        .brand {
            display: flex;
            align-items: center;
            gap: .5rem;
            text-decoration: none;
            color: #fff;
            font-weight: 800;
            font-size: .85rem;
            letter-spacing: .08em;
        }
        .brand-icon {
            width: 2rem;
            height: 2rem;
            border-radius: 6px;
            background: linear-gradient(145deg, var(--blue), var(--blue-deep));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.1rem;
        }
        .nav-links {
            display: flex;
            gap: 1.2rem;
            list-style: none;
        }
        .nav-links a {
            color: var(--muted);
            text-decoration: none;
            font-size: .72rem;
            font-weight: 600;
            transition: color .2s;
            letter-spacing: .04em;
        }
        .nav-links a:hover {
            color: var(--gold);
        }
        @media(max-width:680px) {
            .nav-links {
                display: none;
            }
        }
        .menu-toggle {
            display: none;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            background: rgba(75, 139, 190, .1);
            border: 1px solid var(--border);
            border-radius: 6px;
            width: 40px;
            height: 40px;
            cursor: pointer;
            gap: 4px;
        }
        .menu-toggle span {
            width: 18px;
            height: 2px;
            background: #fff;
            border-radius: 2px;
            transition: .25s;
        }
        .menu-toggle.active span:nth-child(1) {
            transform: rotate(45deg) translate(5px, 5px);
        }
        .menu-toggle.active span:nth-child(2) {
            opacity: 0;
        }
        .menu-toggle.active span:nth-child(3) {
            transform: rotate(-45deg) translate(5px, -5px);
        }
        @media(max-width:680px) {
            .menu-toggle {
                display: flex;
            }
        }
        .drawer-overlay {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, .8);
            z-index: 1050;
            opacity: 0;
            visibility: hidden;
            transition: .2s;
            backdrop-filter: blur(4px);
        }
        .drawer-overlay.active {
            opacity: 1;
            visibility: visible;
        }
        .mobile-drawer {
            position: fixed;
            top: 0;
            right: -300px;
            width: 280px;
            height: 100vh;
            background: var(--panel);
            border-left: 1px solid var(--border);
            z-index: 1100;
            display: flex;
            flex-direction: column;
            transition: right .3s;
            box-shadow: -5px 0 30px rgba(0, 0, 0, .5);
        }
        .mobile-drawer.active {
            right: 0;
        }
        .drawer-hd {
            padding: .8rem;
            border-bottom: 1px solid var(--border);
            display: flex;
            justify-content: flex-end;
        }
        .drawer-close {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            border: 1px solid var(--border);
            background: transparent;
            color: var(--muted);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .drawer-body {
            flex: 1;
            overflow-y: auto;
            padding: .8rem;
        }
        .drawer-body li {
            list-style: none;
            margin-bottom: .5rem;
        }
        .drawer-body a,
        .drawer-body button {
            display: flex;
            align-items: center;
            gap: .6rem;
            width: 100%;
            padding: .7rem .9rem;
            background: rgba(75, 139, 190, .12);
