        .card-grid {
            display: flex;
            flex-direction: column;
            gap: var(--gap);
        }
        .card {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1.25rem;
            display: flex;
            flex-direction: column;
            gap: .55rem;
            transition: border-color .2s, transform .2s, box-shadow .2s;
            text-decoration: none;
            color: inherit;
            cursor: default;
        }
        .card:hover {
            border-color: var(--blue);
