            line-height: 1;
        }
        .card h3,
        .card h4 {
            font-size: .82rem;
            color: var(--text);
        }
        .card p {
            font-size: .74rem;
            margin: 0;
        }
        .badge {
            display: inline-block;
            padding: .12rem .55rem;
