            overflow: hidden;
            border: 1px solid var(--border);
        }
        .code-header {
            background: #0a1a24;
            padding: 0.5rem 1rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            border-bottom: 1px solid var(--border);
            font-size: 0.72rem;
            flex-wrap: wrap;
            gap: 0.5rem;
        }
        .code-actions {
            display: flex;
            gap: 0.5rem;
            flex-wrap: wrap;
        }
        .code-btn {
            padding: 0.35rem 0.8rem;
            font-size: 0.7rem;
            font-weight: 600;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.2s;
            display: inline-flex;
            align-items: center;
            gap: 0.4rem;
            font-family: ''Syne'', sans-serif;
            border: none;
            user-select: none;
        }
        .code-btn:active {
            transform: scale(0.95);
        }
        .copy-btn {
            background: rgba(75, 139, 190, 0.15);
            color: var(--blue-lt);
            border: 1px solid rgba(75, 139, 190, 0.3);
        }
        .copy-btn:hover {
            background: rgba(75, 139, 190, 0.25);
        }
        .copy-btn.copied {
            background: rgba(16, 185, 129, 0.2);
            border-color: var(--green);
            color: var(--green);
        }
        .run-btn {
            background: var(--green);
            color: #000;
            border: none;
            font-weight: 700;
        }
        .run-btn:hover {
            background: #34d399;
            transform: translateY(-1px);
        }
        .run-btn:disabled {
            opacity: 0.6;
            cursor: not-allowed;
            transform: none;
        }
        .output-panel {
            background: #0a1a24;
            border-top: 1px solid var(--border);
            padding: 1rem;
            font-family: ''JetBrains Mono'', monospace;
