        }
        .output-panel.loading {
            color: var(--blue-lt);
        }
        .code-snippet {
            background: var(--code-bg);
            padding: 0.9rem 1rem;
            overflow-x: auto;
            margin: 0;
        }
        .code-snippet pre {
