            border-bottom: 1px dashed var(--border);
        }
        .checklist li:last-child {
            border-bottom: none;
        }
        .checklist li span.check {
            color: var(--blue);
            flex-shrink: 0;
            margin-top: .1rem;
        }
        .oop-block {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1.3rem;
            margin-bottom: 1.2rem;
        }
        .oop-block h3 {
            font-size: .88rem;
            color: var(--gold);
            margin-bottom: .6rem;
            display: flex;
            align-items: center;
            gap: .4rem;
        }
        .oop-block p {
            font-size: .78rem;
            margin-bottom: .8rem;
        }
        .step-list {
            list-style: none;
            counter-reset: step-counter;
            margin: 0.8rem 0 1rem 0;
            padding: 0;
        }
        .step-list li {
            counter-increment: step-counter;
            padding: 0.45rem 0.45rem 0.45rem 2.6rem;
            position: relative;
            font-size: 0.78rem;
            color: var(--muted);
            line-height: 1.6;
            border-bottom: 1px solid rgba(31, 64, 96, 0.25);
        }
        .step-list li:last-child {
            border-bottom: none;
        }
        .step-list li::before {
            content: counter(step-counter);
            position: absolute;
            left: 0.2rem;
            top: 0.45rem;
            width: 1.8rem;
            height: 1.8rem;
            background: rgba(75, 139, 190, 0.15);
            border: 1px solid var(--border);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 0.7rem;
            color: var(--gold);
        }
        .step-list li strong {
            color: var(--text);
        }
        .line-list {
            list-style: none;
            counter-reset: line-counter;
            margin: 0.8rem 0 1rem 0;
            padding: 0;
            background: rgba(75, 139, 190, .04);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
        }
        .line-list li {
            counter-increment: line-counter;
            padding: 0.5rem 0.7rem 0.5rem 3.4rem;
            position: relative;
            font-size: 0.76rem;
            color: var(--muted);
            line-height: 1.55;
            border-bottom: 1px dashed rgba(31, 64, 96, 0.4);
        }
        .line-list li:last-child {
            border-bottom: none;
        }
        .line-list li::before {
            content: "L" counter(line-counter);
            position: absolute;
            left: 0.6rem;
            top: 0.5rem;
            font-family: ''JetBrains Mono'', monospace;
            font-weight: 700;
            font-size: 0.62rem;
            color: var(--teal);
            background: rgba(45, 212, 191, .12);
            border: 1px solid rgba(45, 212, 191, .3);
            border-radius: 4px;
            padding: 0.1rem 0.35rem;
        }
        .line-list li code {
            color: var(--gold);
        }
        .note-new {
            font-size: .74rem;
            color: var(--teal);
            font-style: italic;
            margin-top: .4rem;
        }
        .note-warn {
            font-size: .74rem;
            color: var(--amber);
            font-style: italic;
            margin-top: .4rem;
        }
        .faq-list {
            display: flex;
            flex-direction: column;
            gap: .6rem;
        }
        .faq-item {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            overflow: hidden;
        }
        .faq-q {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 1rem 1.1rem;
            cursor: pointer;
            gap: .8rem;
            min-height: var(--btn-h);
        }
        .faq-q h3 {
            font-size: .8rem;
            font-weight: 600;
            color: var(--text);
            flex: 1;
        }
        .faq-toggle {
            font-size: .9rem;
            color: var(--blue);
            width: 20px;
            text-align: center;
            flex-shrink: 0;
        }
        .faq-a {
            max-height: 0;
            overflow: hidden;
            transition: max-height .28s ease, padding .28s;
        }
        .faq-a.open {
            max-height: 300px;
            padding: 0 1.1rem 1rem;
        }
        .faq-a p {
            font-size: .78rem;
        }
        .table-wrap {
            overflow-x: auto;
            margin-top: 1rem;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            font-size: .76rem;
            min-width: 480px;
        }
        thead tr {
            background: var(--card);
            border-bottom: 2px solid var(--blue);
        }
        th {
            padding: .75rem .8rem;
            text-align: left;
        }
        th:first-child {
            color: var(--gold);
        }
        th:nth-child(2) {
            color: var(--blue);
        }
        td {
            padding: .65rem .8rem;
            border-bottom: 1px solid var(--border);
            color: var(--muted);
        }
        td:nth-child(2) {
            color: var(--green);
            font-weight: 600;
        }
        tbody tr:nth-child(even) {
            background: rgba(75, 139, 190, .03);
        }
        .share-box {
            text-align: center;
            padding: 1rem 0;
        }
        .share-row {
            display: flex;
            flex-direction: row;
            flex-wrap: wrap;
            gap: .6rem;
            margin-top: 1rem;
            justify-content: center;
        }
        .share-btn {
            height: var(--btn-h);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: .4rem;
            border: 1px solid var(--border);
            border-radius: var(--btn-r);
            font-size: .74rem;
            color: var(--muted);
            text-decoration: none;
            transition: .2s;
            font-weight: 600;
            background: var(--card);
            cursor: pointer;
            padding: 0 1rem;
        }
        .share-btn:hover {
            border-color: var(--blue);
            color: var(--text);
            background: rgba(75, 139, 190, .1);
        }
        .share-btn.copy-btn:hover {
            border-color: var(--gold);
            color: var(--gold);
        }
        .floating-share {
            position: fixed;
            right: 20px;
            bottom: 80px;
            display: flex;
            flex-direction: column;
            gap: 10px;
            z-index: 900;
        }
        .floating-share .fs-btn {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            background: var(--card);
            border: 1px solid var(--border);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--muted);
            text-decoration: none;
            font-size: 1.1rem;
            transition: .2s;
            cursor: pointer;
            box-shadow: 0 4px 16px rgba(0, 0, 0, .5);
            position: relative;
        }
        .floating-share .fs-btn:hover {
            border-color: var(--blue);
            color: var(--blue-lt);
            transform: scale(1.08);
        }
        .floating-share .fs-btn .tooltip {
            position: absolute;
            right: 56px;
            background: var(--panel);
            color: var(--text);
            padding: 4px 12px;
            border-radius: 6px;
            font-size: .65rem;
            font-weight: 600;
            border: 1px solid var(--border);
            opacity: 0;
            pointer-events: none;
            transition: .2s;
            white-space: nowrap;
        }
        .floating-share .fs-btn:hover .tooltip {
            opacity: 1;
        }
        .back-top {
            position: fixed;
            right: 20px;
            bottom: 20px;
            width: 44px;
            height: 44px;
            border-radius: 50%;
            background: var(--card);
            border: 1px solid var(--border);
            color: var(--muted);
            font-size: 1.1rem;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            z-index: 900;
            transition: .2s;
            opacity: 0;
            visibility: hidden;
            box-shadow: 0 4px 12px rgba(0, 0, 0, .4);
        }
        .back-top.visible {
            opacity: 1;
            visibility: visible;
        }
        .back-top:hover {
            border-color: var(--blue);
            color: var(--blue-lt);
            transform: translateY(-2px);
        }
        .page-footer {
            padding: 3rem 0 1.5rem;
            background: #1a2535;
            border-top: 1px solid var(--border);
        }
        .footer-grid {
            display: flex;
            flex-direction: column;
            gap: 1.2rem;
            margin-bottom: 1.5rem;
        }
        .footer-col h5 {
            font-size: .72rem;
            font-weight: 800;
            color: var(--gold);
            letter-spacing: .08em;
            text-transform: uppercase;
            margin-bottom: .7rem;
        }
        .footer-col ul {
            list-style: none;
        }
        .footer-col li {
            margin-bottom: .4rem;
        }
        .footer-col a {
            color: rgba(255, 255, 255, .65);
            text-decoration: none;
            font-size: .74rem;
            transition: color .2s;
        }
        .footer-col a:hover {
            color: #fff;
        }
        .copyright {
            border-top: 1px solid var(--border);
            padding-top: 1.2rem;
            text-align: center;
            font-size: .72rem;
            color: var(--muted);
        }
        .copyright a {
            color: rgba(255, 255, 255, .5);
            text-decoration: none;
        }
        .copyright a:hover {
            color: #fff;
        }
        ::-webkit-scrollbar {
            width: 5px;
            height: 5px;
        }
        ::-webkit-scrollbar-track {
            background: var(--border);
        }
        ::-webkit-scrollbar-thumb {
            background: var(--blue);
            border-radius: 3px;
        }
        @media(max-width:480px) {
            .page-col {
                padding: 0 .8rem;
            }
            section {
                padding: 2rem 0;
            }
            .hero {
                padding: 3rem 0 1.5rem;
            }
            .hero h1 {
                font-size: 1.3rem;
            }
            .floating-share {
                right: 10px;
                bottom: 70px;
                gap: 8px;
            }
            .floating-share .fs-btn {
                width: 40px;
                height: 40px;
                font-size: .9rem;
            }
            .floating-share .fs-btn .tooltip {
                display: none;
            }
            .back-top {
                width: 36px;
                height: 36px;
                right: 10px;
                bottom: 10px;
                font-size: .9rem;
            }
            .share-row {
                flex-direction: column;
                align-items: center;
            }
            .share-btn {
                width: 100%;
                max-width: 240px;
            }
            .code-header {
                flex-direction: column;
                align-items: stretch;
                gap: 0.4rem;
            }
            .code-actions {
                justify-content: flex-start;
            }
            .code-btn {
                font-size: 0.65rem;
                padding: 0.25rem 0.6rem;
            }
            .output-panel {
                font-size: 0.7rem;
                padding: 0.7rem;
            }
        }
        @media(max-width:768px) {
            .floating-share {
                right: 14px;
                bottom: 76px;
                gap: 8px;
            }
            .floating-share .fs-btn {
                width: 42px;
                height: 42px;
                font-size: 1rem;
            }
            .floating-share .fs-btn .tooltip {
                display: none;
            }
        }
        .toc-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 0.6rem;
            margin-top: 1.2rem;
        }
        .toc-grid a {
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            padding: 0.7rem 0.8rem;
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            color: var(--muted);
            text-decoration: none;
            font-size: 0.7rem;
            font-weight: 600;
            transition: border-color .2s, color .2s, background .2s, transform .15s;
            min-height: 44px;
            line-height: 1.3;
            word-break: break-word;
        }
        .toc-grid a:hover {
            border-color: var(--blue);
            color: var(--text);
            background: rgba(75, 139, 190, .08);
            transform: translateY(-2px);
        }
        @media(max-width:480px) {
            .toc-grid {
                grid-template-columns: 1fr 1fr;
            }
            .toc-grid a {
                font-size: 0.6rem;
                padding: 0.5rem 0.4rem;
                min-height: 38px;
            }
        }
        .pyodide-status {
            font-size: 0.65rem;
            color: var(--muted);
            padding: 0.2rem 0.6rem;
            border-radius: 12px;
            background: var(--panel);
            border: 1px solid var(--border);
            display: inline-flex;
            align-items: center;
            gap: 0.3rem;
        }
        .pyodide-status .dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--green);
            display: inline-block;
            animation: pulse-dot 1.5s infinite;
        }
        @keyframes pulse-dot {
            0%,
            100% {
                opacity: 1;
            }
            50% {
                opacity: 0.3;
            }
        }
        .intro-grid {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 1rem;
            margin: 1.2rem 0;
        }
        .intro-grid .intro-item {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1rem 1.1rem;
            text-align: center;
            transition: border-color .2s;
        }
        .intro-grid .intro-item:hover {
            border-color: var(--blue);
        }
        .intro-grid .intro-item i {
            font-size: 1.6rem;
            color: var(--gold);
            margin-bottom: 0.4rem;
            display: block;
        }
        .intro-grid .intro-item h4 {
            font-size: 0.78rem;
            color: var(--text);
            margin-bottom: 0.2rem;
        }
        .intro-grid .intro-item p {
            font-size: 0.68rem;
            margin: 0;
        }
        @media(max-width:600px) {
            .intro-grid {
                grid-template-columns: 1fr 1fr;
            }
        }
        @media(max-width:400px) {
            .intro-grid {
                grid-template-columns: 1fr;
            }
        }
        .why-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1rem;
            margin: 1rem 0;
        }
        .why-grid .why-item {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1rem 1.1rem;
            border-left: 3px solid var(--blue);
        }
        .why-grid .why-item h4 {
            font-size: 0.8rem;
            color: var(--gold);
            margin-bottom: 0.2rem;
        }
        .why-grid .why-item p {
            font-size: 0.72rem;
            margin: 0;
        }
        @media(max-width:500px) {
            .why-grid {
                grid-template-columns: 1fr;
            }
        }
        .sig-grid {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 1rem;
            margin: 1rem 0;
        }
        .sig-grid .sig-item {
            background: var(--card);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 1rem 1rem;
            text-align: center;
            transition: transform .2s;
        }
        .sig-grid .sig-item:hover {
            transform: translateY(-3px);
            border-color: var(--blue);
        }
        .sig-grid .sig-item .sig-icon {
            font-size: 1.8rem;
            color: var(--blue-lt);
            display: block;
            margin-bottom: 0.3rem;
        }
        .sig-grid .sig-item h4 {
            font-size: 0.78rem;
            color: var(--text);
            margin-bottom: 0.2rem;
        }
        .sig-grid .sig-item p {
            font-size: 0.68rem;
            margin: 0;
        }
        @media(max-width:600px) {
            .sig-grid {
                grid-template-columns: 1fr 1fr;
            }
        }
        @media(max-width:400px) {
            .sig-grid {
                grid-template-columns: 1fr;
            }
        }
        .outro-box {
            background: radial-gradient(ellipse at 50% 100%, rgba(75, 139, 190, .12) 0%, transparent 70%);
            border: 1px solid var(--border);
            border-radius: var(--card-r);
            padding: 2rem 1.8rem;
            text-align: center;
            margin: 1.5rem 0;
        }
        .outro-box h2 {
            color: var(--gold);
            font-size: 1.3rem;
            margin-bottom: 0.6rem;
        }
        .outro-box p {
            font-size: 0.85rem;
            max-width: 600px;
            margin: 0 auto 1rem;
            line-height: 1.8;
        }
        .outro-box .outro-cta {
            display: flex;
            flex-wrap: wrap;
            gap: 0.6rem;
            justify-content: center;
            margin-top: 1.2rem;
        }
    </style>
</head>
