                        <div class="code-snippet"><pre><span class="kw">from</span> apscheduler.schedulers.background <span class="kw">import</span> BackgroundScheduler
<span class="kw">from</span> apscheduler.triggers.cron <span class="kw">import</span> CronTrigger
<span class="kw">import</span> time

<span class="kw">def</span> <span class="fn">cron_task</span>():
    <span class="fn">print</span>(<span class="st">f"⏰ Cron task ran at {time.strftime(''%Y-%m-%d %H:%M:%S'')}"</span>)

<span class="kw">def</span> <span class="fn">cron_demo</span>():
    scheduler = BackgroundScheduler()
    scheduler.add_job(cron_task, CronTrigger(second=<span class="st">"*/2"</span>))
    scheduler.start()
    <span class="fn">print</span>(<span class="st">"⏳ Cron scheduler running for 6 seconds..."</span>)

    time.sleep(6)
    scheduler.shutdown()
    <span class="fn">print</span>(<span class="st">"✅ Cron scheduler stopped"</span>)

cron_demo()</pre></div>
