                    </ul>

                    <div class="code-container" data-code=''from bs4 import BeautifulSoup

def soup_demo():
    html = """
    &lt;html&gt;
        &lt;body&gt;
            &lt;h1&gt;Automation Tutorial&lt;/h1&gt;
            &lt;ul class=&quot;links&quot;&gt;
                &lt;li&gt;&lt;a href=&quot;/lesson1&quot;&gt;Lesson 1&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a href=&quot;/lesson2&quot;&gt;Lesson 2&lt;/a&gt;&lt;/li&gt;
                &lt;li&gt;&lt;a href=&quot;/lesson3&quot;&gt;Lesson 3&lt;/a&gt;&lt;/li&gt;
            &lt;/ul&gt;
            &lt;p class=&quot;desc&quot;&gt;Learn Python automation.&lt;/p&gt;
        &lt;/body&gt;
    &lt;/html&gt;
    """
    soup = BeautifulSoup(html, "html.parser")

    title = soup.find("h1").text
    print(f"📄 Title: {title}")

    links = soup.find_all("a")
    print(f"🔗 Found {len(links)} links:")
    for link in links:
        print(f"  - {link.text} → {link.get(&#39;href&#39;)}")

    desc = soup.find("p", class_="desc")
    print(f"📝 Description: {desc.text if desc else &#39;Not found&#39;}")

soup_demo()''>
