    <script>
        (function() {
            ''use strict'';

            var pbar = document.getElementById(''pbar'');
            window.addEventListener(''scroll'', function() {
                var h = document.documentElement;
                var pct = h.scrollTop / (h.scrollHeight - h.clientHeight) * 100;
                if (pbar) pbar.style.width = Math.min(pct, 100) + ''%'';
            }, { passive: true });

            var menuToggle = document.getElementById(''menuToggle'');
            var drawer = document.getElementById(''mobileDrawer'');
            var overlay = document.getElementById(''drawerOverlay'');
            var drawerClose = document.getElementById(''drawerClose'');

            function closeDrawer() {
                if (menuToggle) menuToggle.classList.remove(''active'');
                if (drawer) drawer.classList.remove(''active'');
                if (overlay) overlay.classList.remove(''active'');
                document.body.style.overflow = '''';
            }
            if (menuToggle) {
                menuToggle.addEventListener(''click'', function(e) {
                    e.stopPropagation();
                    var open = drawer.classList.toggle(''active'');
                    menuToggle.classList.toggle(''active'', open);
                    overlay.classList.toggle(''active'', open);
                    document.body.style.overflow = open ? ''hidden'' : '''';
                });
            }
            if (overlay) overlay.addEventListener(''click'', closeDrawer);
            if (drawerClose) drawerClose.addEventListener(''click'', closeDrawer);
            document.addEventListener(''keydown'', function(e) { if (e.key === ''Escape'') closeDrawer(); });

            document.querySelectorAll(''.drawer-body button[data-href]'').forEach(function(btn) {
                btn.addEventListener(''click'', function() {
                    var target = document.querySelector(btn.dataset.href);
                    if (target) { target.scrollIntoView({ behavior: ''smooth'' });
                        closeDrawer(); }
                });
            });

            window.toggleFaq = function(qEl) {
                var item = qEl.closest(''.faq-item'');
                var answer = item.querySelector(''.faq-a'');
                var toggle = qEl.querySelector(''.faq-toggle'');
                var isOpen = answer.classList.contains(''open'');
                document.querySelectorAll(''.faq-a.open'').forEach(function(a) {
                    a.classList.remove(''open'');
                    a.closest(''.faq-item'').querySelector(''.faq-toggle'').textContent = ''+'';
                });
                if (!isOpen) { answer.classList.add(''open'');
                    toggle.textContent = ''−''; }
            };

            var backTop = document.getElementById(''backTop'');
            window.addEventListener(''scroll'', function() {
                backTop.classList.toggle(''visible'', window.scrollY > 500);
            }, { passive: true });
            backTop.addEventListener(''click'', function() {
                window.scrollTo({ top: 0, behavior: ''smooth'' });
            });

            var PAGE_URL = encodeURIComponent(''https://poetic-bytes.vercel.app/python-automation.html'');
            var PAGE_TITLE = encodeURIComponent(''Python Automation – Learn Python Free 2026 | Poetic Bytes'');

            function shareTo(url) {
                window.open(url, ''_blank'', ''width=600,height=500,noopener,noreferrer'');
            }
            document.querySelectorAll(''#shareFb,#shareFbBottom'').forEach(function(el) {
                if (el) el.addEventListener(''click'', function(e) { e.preventDefault();
                    shareTo(''https://www.facebook.com/sharer/sharer.php?u='' + PAGE_URL); });
            });
            document.querySelectorAll(''#shareTw,#shareTwBottom'').forEach(function(el) {
                if (el) el.addEventListener(''click'', function(e) { e.preventDefault();
                    shareTo(''https://twitter.com/intent/tweet?url='' + PAGE_URL + ''&text='' + PAGE_TITLE +
                        ''&via=PoeticGlenn''); });
            });
            document.querySelectorAll(''#shareLi,#shareLiBottom'').forEach(function(el) {
                if (el) el.addEventListener(''click'', function(e) { e.preventDefault();
                    shareTo(''https://www.linkedin.com/sharing/share-offsite/?url='' + PAGE_URL); });
            });
            document.querySelectorAll(''#shareWa,#shareWaBottom'').forEach(function(el) {
                if (el) el.addEventListener(''click'', function(e) { e.preventDefault();
                    shareTo(''https://api.whatsapp.com/send?text='' + PAGE_TITLE + ''%20'' + PAGE_URL); });
            });
            document.querySelectorAll(''#shareTg,#shareTgBottom'').forEach(function(el) {
                if (el) el.addEventListener(''click'', function(e) { e.preventDefault();
                    shareTo(''https://t.me/share/url?url='' + PAGE_URL + ''&text='' + PAGE_TITLE); });
            });

            function copyLink(btn) {
                var url = ''https://poetic-bytes.vercel.app/python-automation.html'';
                if (navigator.clipboard) {
                    navigator.clipboard.writeText(url).then(function() {
                        var orig = btn.innerHTML;
                        btn.innerHTML = ''<i class="fas fa-check"></i> Copied!'';
                        setTimeout(function() { btn.innerHTML = orig; }, 2000);
                    }).catch(function() { fallbackCopy(url, btn); });
                } else { fallbackCopy(url, btn); }
            }

            function fallbackCopy(text, btn) {
                var ta = document.createElement(''textarea'');
                ta.value = text;
                ta.style.cssText = ''position:fixed;opacity:0;left:-9999px'';
                document.body.appendChild(ta);
                ta.select();
                document.execCommand(''copy'');
                document.body.removeChild(ta);
                var orig = btn.innerHTML;
                btn.innerHTML = ''<i class="fas fa-check"></i> Copied!'';
                setTimeout(function() { btn.innerHTML = orig; }, 2000);
            }
            var copyBtn = document.getElementById(''copyLinkBtn'');
            var copyBottom = document.getElementById(''copyLinkBottom'');
            if (copyBtn) copyBtn.addEventListener(''click'', function() { copyLink(this); });
            if (copyBottom) copyBottom.addEventListener(''click'', function() { copyLink(this); });

            function dedent(code) {
                var lines = code.split(''\n'');
                var minIndent = Infinity;
                for (var i = 0; i < lines.length; i++) {
                    var line = lines[i];
                    if (line.trim().length === 0) continue;
                    var match = line.match(/^(\s+)/);
                    if (match) { if (match[1].length < minIndent) minIndent = match[1].length; } else { minIndent = 0;
                        break; }
                }
                if (!isFinite(minIndent) || minIndent === 0) return code;
                return lines.map(function(l) { return l.trim().length === 0 ? l : l.slice(minIndent); }).join(''\n'');
            }

            var BROWSER_PREAMBLE = `
import sys as _sys, types as _types, builtins as _builtins

_gp = _types.ModuleType(''getpass'')
def _getpass_fn(prompt=''Password: '', stream=None):
    from js import prompt as _jsprompt
    result = _jsprompt(prompt)
    return result if result is not None else ''''
_gp.getpass = _getpass_fn
_gp.getuser = lambda: ''browser_user''
_sys.modules[''getpass''] = _gp

_sys.argv = [''script.py'', ''--help'']
`;

            var pyodideReady = false;
            var pyodideInstance = null;

            async function loadPyodideAndPackages() {
                if (!pyodideReady) {
                    pyodideInstance = await loadPyodide({
                        indexURL: ''https://cdn.jsdelivr.net/pyodide/v0.26.1/full/''
                    });
                    pyodideReady = true;
                }
                return pyodideInstance;
            }

            function makePrintFn(outputRef) {
                return function(text) {
                    outputRef.text += text;
                };
            }

            async function runCode(code, outputEl, runBtn) {
                runBtn.disabled = true;
                var originalHTML = runBtn.innerHTML;
                runBtn.innerHTML = ''<i class="fas fa-spinner fa-spin"></i> Loading…'';

                outputEl.style.display = ''block'';
                outputEl.className = ''output-panel loading'';
                outputEl.textContent = ''Loading Python runtime… (first run may take 8–12 s)\n\n'';

                try {
                    var pyodide = await loadPyodideAndPackages();
                    outputEl.textContent = '''';
                    outputEl.className = ''output-panel'';

                    var clean = dedent(code).trim();
                    var outputRef = { text: '''' };
                    var printFn = makePrintFn(outputRef);

                    pyodide.globals.set(''_js_print'', printFn);
                    pyodide.globals.set(''_js_input'', function(promptText) {
                        var result = prompt(promptText != null ? String(promptText) : '''');
                        return result !== null ? result : '''';
                    });

                    await pyodide.runPythonAsync(`
import builtins

def _print(*args, sep='' '', end=''\\n'', file=None, flush=False):
    _js_print(sep.join(str(x) for x in args) + (end if end != ''\\n'' else ''''))

def _input(prompt=''''):
    return _js_input(str(prompt) if prompt else '''')

builtins.print = _print
builtins.input = _input
`);

                    await pyodide.runPythonAsync(BROWSER_PREAMBLE);

                    try {
                        await pyodide.runPythonAsync(clean);
                    } catch (innerErr) {
                        var innerMsg = innerErr && innerErr.message ? innerErr.message : String(innerErr);
                        if (innerMsg.indexOf(''SystemExit'') !== -1) {
                            outputRef.text += ''\n[Program exited via SystemExit]\n'';
                            outputEl.textContent = outputRef.text;
                            outputEl.style.color = ''#f59e0b'';
                            return;
                        }
                        throw innerErr;
                    }

                    var finalOutput = outputRef.text;
                    outputEl.textContent = finalOutput || ''✓ Code executed successfully (no output).'';
                    outputEl.style.color = ''#4ade80'';

                } catch (err) {
                    outputEl.className = ''output-panel error'';
                    var msg = err && err.message ? err.message : String(err);
                    outputEl.textContent = ''Error:\n'' + msg;
                    outputEl.style.color = ''#f87171'';
                } finally {
                    runBtn.disabled = false;
                    runBtn.innerHTML = originalHTML;
                }
            }

            function copyCode(btn, code) {
                var clean = dedent(code).trim();
                if (navigator.clipboard) {
                    navigator.clipboard.writeText(clean).then(function() { flashCopied(btn); })
                        .catch(function() { fallbackCopyCode(btn, clean); });
                } else { fallbackCopyCode(btn, clean); }
            }

            function fallbackCopyCode(btn, code) {
                var ta = document.createElement(''textarea'');
                ta.value = code;
                ta.style.cssText = ''position:fixed;opacity:0;left:-9999px'';
                document.body.appendChild(ta);
                ta.select();
                document.execCommand(''copy'');
                document.body.removeChild(ta);
                flashCopied(btn);
            }

            function flashCopied(btn) {
                var orig = btn.innerHTML;
                btn.innerHTML = ''<i class="fas fa-check"></i> Copied!'';
                btn.classList.add(''copied'');
                setTimeout(function() { btn.innerHTML = orig;
                    btn.classList.remove(''copied''); }, 2000);
            }

            function initCodeContainers() {
                document.querySelectorAll(''.code-container'').forEach(function(container) {
                    if (container.classList.contains(''no-run'')) {
                        var cpOnly = container.querySelector(''.copy-btn'');
                        var preOnly = container.querySelector(''.code-snippet pre'');
                        if (cpOnly && preOnly) {
                            cpOnly.addEventListener(''click'', function(e) {
                                e.stopPropagation();
                                copyCode(cpOnly, preOnly.textContent);
                            });
                        }
                        return;
                    }

                    var codeAttr = container.getAttribute(''data-code'');
                    if (!codeAttr) {
                        var pre = container.querySelector(''.code-snippet pre'');
                        if (pre) codeAttr = pre.textContent;
                    }
                    if (!codeAttr) return;

                    var cpBtn = container.querySelector(''.copy-btn'');
                    var rnBtn = container.querySelector(''.run-btn'');
                    var outEl = container.querySelector(''.output-panel'');

                    if (cpBtn) {
                        cpBtn.addEventListener(''click'', function(e) {
                            e.stopPropagation();
                            copyCode(cpBtn, codeAttr);
                        });
                    }
                    if (rnBtn && outEl) {
                        rnBtn.addEventListener(''click'', function(e) {
                            e.stopPropagation();
                            runCode(codeAttr, outEl, rnBtn);
                        });
                    }
                });
            }

            if (document.readyState === ''complete'') { initCodeContainers(); } else { window.addEventListener(''load'',
                    initCodeContainers); }

        })();
    </script>

